1. **Graph Representation**: Represent the graph using an adjacency list.
2. **Cycle Detection**: Use DFS to detect cycles in the graph.
3. **Directing Edges**: Direct the undirected edges to ensure the graph remains acyclic.

Here's the Python code to implement this approach:

```python
import sys
from collections import defaultdict, deque

sys.setrecursionlimit(200005)

def dfs(node, parent):
    visited[node] = True
    rec_stack[node] = True

    for neighbor in graph[node]:
        if not visited[neighbor]:
            if dfs(neighbor, node):
                return True
        elif rec_stack[neighbor]:
            return True

    rec_stack[node] = False
    return False

def add_edge(x, y):
    graph[x].append(y)

def solve(n, m, edges):
    global graph, visited, rec_stack
    graph = defaultdict(list)
    visited = [False] * (n + 1)
    rec_stack = [False] * (n + 1)

    # Directed edges
    for t, x, y in edges:
        if t == 1:
            add_edge(x, y)

    # Check for cycles
    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i, -1):
                return "NO"

    # Direct the remaining edges
    result = []
    for t, x, y in edges:
        if t == 0:
            if not visited[x]:
                visited[x] = True
                result.append(f"{x} {y}")
            elif not visited[y]:
                visited[y] = True
                result.append(f"{y} {x}")

    # Output the result
    print("YES")
    for res in result:
        print(res)
    return "YES"

def main():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        edges = [list(map(int, input().split())) for _ in range(m)]
        solve(n, m, edges)

if __name__ == "__main__":
    main()
```

